// Converts Dying Skies instrument JSON into spec patches for the engines.

// Tone.js defaults for options the JSON leaves out.
const SYNTH_ENVELOPE = { attack: 0.005, decay: 0.1, sustain: 0.3, release: 1 };
const MONO_VOICE = {
  oscillator: { type: "sawtooth" },
  envelope: { attack: 0.005, decay: 0.1, sustain: 0.9, release: 1 },
  filter: { type: "lowpass", frequency: 350, Q: 1, rolloff: -12 },
  filterEnvelope: { attack: 0.6, decay: 0.2, sustain: 0.5, release: 2, baseFrequency: 200, octaves: 3 },
};
const DUO_VOICE = {
  ...MONO_VOICE,
  envelope: { attack: 0.01, decay: 0, sustain: 1, release: 0.5 },
  filterEnvelope: { attack: 0.01, decay: 0, sustain: 1, release: 0.5, baseFrequency: 200, octaves: 3 },
};
const FM_ENVELOPE = { attack: 0.01, decay: 0.01, sustain: 1, release: 0.5 };
const FM_MODULATION_ENVELOPE = { attack: 0.5, decay: 0, sustain: 1, release: 0.5 };
const MEMBRANE_ENVELOPE = { attack: 0.001, decay: 0.4, sustain: 0.01, release: 1.4 };
const NOISE_ENVELOPE = { attack: 0.01, decay: 0.1, sustain: 0, release: 1 };

/** Room size matching the old tester's six-second reverb. */
export const REVERB_ROOM = 6 / 14;

const monoVoice = (options = {}, defaults) => ({
  oscillator: { ...defaults.oscillator, ...options.oscillator },
  envelope: { ...defaults.envelope, ...options.envelope },
  filter: { ...defaults.filter, ...options.filter },
  filterEnvelope: { ...defaults.filterEnvelope, ...options.filterEnvelope },
});

// One builder per Tone class, from its options to a spec source.
const SOURCES = {
  Synth: (options) => ({
    kind: "synth",
    oscillator: { type: "triangle", ...options.oscillator },
    envelope: { ...SYNTH_ENVELOPE, ...options.envelope },
  }),
  MonoSynth: (options) => ({ kind: "mono", ...monoVoice(options, MONO_VOICE), portamento: options.portamento }),
  FMSynth: (options) => ({
    kind: "fm",
    oscillator: { type: "sine", ...options.oscillator },
    modulator: { type: "square", ...options.modulation },
    harmonicity: options.harmonicity ?? 3,
    modulationIndex: options.modulationIndex ?? 10,
    envelope: { ...FM_ENVELOPE, ...options.envelope },
    modulationEnvelope: { ...FM_MODULATION_ENVELOPE, ...options.modulationEnvelope },
  }),
  DuoSynth: (options) => ({
    kind: "duo",
    voices: [monoVoice(options.voice0, DUO_VOICE), monoVoice(options.voice1, DUO_VOICE)],
    harmonicity: options.harmonicity ?? 1.5,
    vibratoRate: options.vibratoRate ?? 5,
    vibratoAmount: options.vibratoAmount ?? 0.5,
    portamento: options.portamento,
  }),
  MembraneSynth: (options) => ({
    kind: "membrane",
    oscillator: { type: "sine", ...options.oscillator },
    envelope: { ...MEMBRANE_ENVELOPE, ...options.envelope },
    pitchDecay: options.pitchDecay ?? 0.05,
    octaves: options.octaves ?? 10,
  }),
  NoiseSynth: (options) => ({ kind: "noise", noise: options.noise?.type ?? "white", envelope: { ...NOISE_ENVELOPE, ...options.envelope } }),
};

const sourceFor = (raw) => {
  const build = SOURCES[raw.synth];
  if (build === undefined) throw new Error(`no spec source for Tone class "${raw.synth}"`);
  return build(raw.options);
};

const EFFECTS = {
  Distortion: (options) => ({ type: "distortion", amount: options.distortion, wet: options.wet }),
  Chebyshev: (options) => ({ type: "chebyshev", order: options.order, wet: options.wet }),
  Chorus: ({ frequency, delayTime, depth, spread, wet }) => ({ type: "chorus", frequency, delayTime, depth, spread, wet }),
  Tremolo: ({ frequency, depth, spread, wet }) => ({ type: "tremolo", frequency, depth, spread, wet }),
  Vibrato: ({ frequency, depth, wet }) => ({ type: "vibrato", frequency, depth, wet }),
  AutoFilter: ({ frequency, baseFrequency, octaves, depth = 1, wet }) => ({ type: "autofilter", frequency, baseFrequency, octaves, depth, wet }),
  StereoWidener: (options) => ({ type: "widener", width: options.width }),
  FeedbackDelay: ({ delayTime, feedback, wet }) => ({ type: "feedbackdelay", delayTime, feedback, wet }),
  PingPongDelay: ({ delayTime, feedback, wet }) => ({ type: "pingpong", delayTime, feedback, wet }),
  Reverb: ({ decay, preDelay = 0.01, wet }) => ({ type: "reverb", decay, preDelay, wet }),
};

const effectFor = ([name, options]) => {
  const convert = EFFECTS[name];
  if (convert === undefined) throw new Error(`no spec effect for Tone class "${name}"`);
  return convert(options);
};

/** One spec instrument from a set role or kit piece. */
export const instrumentSpec = (id, raw, reverbSend) => ({
  id,
  source: sourceFor(raw),
  polyphony: raw.polyphony ?? 1,
  volume: 20 * Math.log10(raw.gain),
  effects: [...(raw.filter === undefined ? [] : [{ type: "filter", filter: raw.filter }]), ...raw.effects.map(effectFor)],
  reverbSend,
});

const kitRole = (piece, index) => {
  if (index === 0) return "kick";
  if (index === 1) return "snare";
  return piece.synth === "NoiseSynth" ? "hat" : "perc";
};

/** Patch, roles and pre-render hints for a set role or a kit. */
export const testRig = (raw, role, notes, reverbSend) => {
  const reverb = { roomSize: REVERB_ROOM };
  if (raw.kind !== "kit") {
    return {
      patch: { instruments: [instrumentSpec("voice", raw, reverbSend)], reverb, master: { volume: 0 } },
      roles: { voice: role },
      hints: { voice: { notes } },
    };
  }
  const ids = raw.pieces.map((piece, index) => `piece${index}`);
  return {
    patch: { instruments: raw.pieces.map((piece, index) => instrumentSpec(ids[index], piece, reverbSend)), reverb, master: { volume: 0 } },
    roles: Object.fromEntries(raw.pieces.map((piece, index) => [ids[index], kitRole(piece, index)])),
    hints: Object.fromEntries(raw.pieces.map((piece, index) => [ids[index], { notes: [piece.note ?? "C2"] }])),
  };
};
