/** Engine parts shared by live and offline sessions: notes, ramps, events. */
import type { Engine, Instrument, Note, OfflineOptions, RampTarget, Score, Time } from "../../spec/api.ts";
import { encodeEvent, EventType, MASTER_INDEX, RAMP_TARGET_CODES, type EventRecord } from "./core/events.ts";
import { noteToMidi } from "./core/notation.ts";
import type { CompiledPatch } from "./core/program.ts";
import type { WorkletLink } from "./link.ts";
import { BeatTransport } from "./transport.ts";

/** The pieces a session is built from. */
export interface SessionParts {
  readonly context: BaseAudioContext;
  readonly node: AudioWorkletNode;
  readonly link: WorkletLink;
  readonly compiled: CompiledPatch;
  readonly leadSeconds: number;
}

/** Handle that turns instrument calls into timed events. */
class InstrumentHandle implements Instrument {
  private readonly session: Session;
  private readonly index: number;

  constructor(session: Session, index: number) {
    this.session = session;
    this.index = index;
  }

  triggerAttack(note: Note, time?: number, velocity = 1): void {
    this.session.noteOn(this.index, noteToMidi(note), time ?? this.session.now, velocity);
  }

  triggerRelease(note?: Note, time?: number): void {
    const startTime = time ?? this.session.now;
    if (note === undefined) this.session.post({ type: EventType.ReleaseAll, instrument: this.index, time: startTime });
    else this.session.post({ type: EventType.NoteOff, instrument: this.index, time: startTime, pitch: noteToMidi(note) });
  }

  triggerAttackRelease(note: Note, duration: Time, time?: number, velocity = 1): void {
    const startTime = time ?? this.session.now;
    const noteId = this.session.noteOn(this.index, noteToMidi(note), startTime, velocity);
    const end = startTime + this.session.transport.toSeconds(duration);
    this.session.post({ type: EventType.NoteOff, instrument: this.index, time: end, noteId });
  }

  releaseAll(time?: number): void {
    this.session.post({ type: EventType.ReleaseAll, instrument: this.index, time: time ?? this.session.now });
  }
}

/** Common engine behaviour over one DSP node. */
export abstract class Session implements Engine {
  readonly context: BaseAudioContext;
  readonly transport: BeatTransport;
  protected readonly node: AudioWorkletNode;
  protected readonly link: WorkletLink;
  private readonly compiled: CompiledPatch;
  private readonly leadSeconds: number;
  private readonly handles = new Map<string, InstrumentHandle>();
  private batch: number[] = [];
  private flushQueued = false;
  private noteCount = 0;

  constructor(parts: SessionParts) {
    this.context = parts.context;
    this.node = parts.node;
    this.link = parts.link;
    this.compiled = parts.compiled;
    this.leadSeconds = parts.leadSeconds;
    this.transport = new BeatTransport({ now: () => this.now, post: (record) => this.post(record) });
  }

  abstract get state(): AudioContextState | "interrupted";
  abstract unlock(): Promise<void>;
  abstract resume(): Promise<void>;
  abstract suspend(): Promise<void>;
  abstract renderOffline(score: Score, options: OfflineOptions): Promise<Float32Array[]>;

  get now(): number {
    return this.context.currentTime + this.leadSeconds;
  }

  instrument(id: string): Instrument {
    const cached = this.handles.get(id);
    if (cached) return cached;
    const index = this.compiled.instrumentIds.indexOf(id);
    if (index < 0) throw new Error(`Unknown instrument "${id}"`);
    const handle = new InstrumentHandle(this, index);
    this.handles.set(id, handle);
    return handle;
  }

  /** Rest form keeps the spec's five arguments under the lint limit. */
  ramp(...request: Parameters<Engine["ramp"]>): void {
    const [target, value, duration, time, instrumentId] = request;
    const code = RAMP_TARGET_CODES[target];
    if (code === undefined) throw new Error(`Unknown ramp target "${target}"`);
    const instrument = this.rampIndex(target, instrumentId);
    this.post({ type: EventType.Ramp, instrument, time: time ?? this.now, pitch: code, value, duration });
  }

  private rampIndex(target: RampTarget, instrumentId: string | undefined): number {
    if (instrumentId === undefined) {
      if (target === "reverbSend") throw new Error("reverbSend ramps need an instrument id");
      if (target === "filterFrequency" && !this.compiled.masterHasFilter) throw new Error("The master chain has no filter to ramp");
      return MASTER_INDEX;
    }
    const index = this.compiled.instrumentIds.indexOf(instrumentId);
    if (index < 0) throw new Error(`Unknown instrument "${instrumentId}"`);
    if (target === "filterFrequency" && !this.compiled.filterTargets.has(instrumentId)) {
      throw new Error(`Instrument "${instrumentId}" has no filter effect to ramp`);
    }
    return index;
  }

  /** Queues a note-on and returns its id for the matching note-off. */
  noteOn(instrument: number, pitch: number, time: number, velocity: number): number {
    this.noteCount += 1;
    this.post({ type: EventType.NoteOn, instrument, time, pitch, value: velocity, noteId: this.noteCount });
    return this.noteCount;
  }

  /** Queues an event, tagged with the running transport callback. */
  post(record: EventRecord): void {
    encodeEvent({ ...record, tag: record.tag ?? this.transport.currentTag }, this.batch);
    if (this.flushQueued) return;
    this.flushQueued = true;
    queueMicrotask(() => this.flush());
  }

  /** Sends every queued event to the processor now. */
  flush(): void {
    this.flushQueued = false;
    if (this.batch.length === 0) return;
    const records = Float64Array.from(this.batch);
    this.batch = [];
    this.link.send({ type: "events", records }, [records.buffer]);
  }

  dispose(): void {
    this.link.send({ type: "stop" });
    this.node.disconnect();
  }
}
