/** Offline rendering: the same DSP worklet in an OfflineAudioContext, in chunks. */
import type { OfflineOptions, Score } from "../../spec/api.ts";
import type { WorkletLink } from "./link.ts";
import { createDspNode, type EngineAssets } from "./loader.ts";
import { Session } from "./session.ts";

const BLOCK_FRAMES = 128;

/** Session inside an offline render; lifecycle calls do nothing. */
class OfflineSession extends Session {
  get state(): AudioContextState {
    return this.context.state;
  }

  unlock(): Promise<void> {
    return Promise.resolve();
  }

  resume(): Promise<void> {
    return Promise.resolve();
  }

  suspend(): Promise<void> {
    return Promise.resolve();
  }

  renderOffline(): Promise<Float32Array[]> {
    return Promise.reject(new Error("renderOffline cannot run inside an offline render"));
  }
}

function chunkFramesFor(chunkSeconds: number | undefined, sampleRate: number, totalFrames: number): number {
  if (chunkSeconds === undefined || !(chunkSeconds > 0)) return totalFrames;
  return Math.max(1, Math.round((chunkSeconds * sampleRate) / BLOCK_FRAMES)) * BLOCK_FRAMES;
}

function toChannelCount(left: Float32Array, right: Float32Array, count: number): Float32Array[] {
  if (count === 1) return [left.map((sample, index) => (sample + right[index]) * 0.5)];
  const extra = Array.from({ length: Math.max(count - 2, 0) }, () => new Float32Array(left.length));
  return [left, right, ...extra];
}

/** Resolves after every chunk reached onChunk, in order. */
function deliverChunks(link: WorkletLink, chunkCount: number, options: OfflineOptions, fail: (reason: unknown) => void): Promise<void> {
  return new Promise((resolve) => {
    let delivered = 0;
    link.listenForChunks((chunk) => {
      try {
        options.onChunk?.(toChannelCount(chunk.left, chunk.right, options.channels ?? 2), chunk.index);
      } catch (failure) {
        fail(failure);
        return;
      }
      delivered += 1;
      if (delivered === chunkCount) resolve();
    });
  });
}

/** Runs callbacks up to a time, then waits for the DSP. */
async function scheduleThrough(session: Session, link: WorkletLink, untilTime: number): Promise<void> {
  session.transport.advance(untilTime);
  session.flush();
  await link.sync();
}

/** Renders a score offline and returns every output channel. */
export async function renderScore(assets: EngineAssets, score: Score, options: OfflineOptions, defaultRate: number): Promise<Float32Array[]> {
  if (!(options.duration > 0)) throw new Error(`Offline duration must be positive, got ${options.duration}`);
  const sampleRate = options.sampleRate ?? defaultRate;
  const totalFrames = Math.ceil(options.duration * sampleRate);
  const context = new OfflineAudioContext(options.channels ?? 2, totalFrames, sampleRate);
  const { node, link } = await createDspNode(context, assets);
  const session = new OfflineSession({ context, node, link, compiled: assets.compiled, leadSeconds: 0 });
  const chunkFrames = chunkFramesFor(options.chunkSeconds, sampleRate, totalFrames);
  const chunkCount = Math.ceil(totalFrames / chunkFrames);
  let fail: (reason: unknown) => void = () => undefined;
  const failure = new Promise<never>((_, reject) => {
    fail = reject;
  });
  const wantsChunks = options.onChunk !== undefined;
  const delivered = wantsChunks ? deliverChunks(link, chunkCount, options, fail) : Promise.resolve();
  if (wantsChunks) link.send({ type: "capture", chunkFrames, totalFrames });
  score(session);
  const chunkSeconds = chunkFrames / sampleRate;
  await scheduleThrough(session, link, chunkSeconds);
  for (let chunk = 1; chunk < chunkCount; chunk += 1) {
    const boundary = chunk * chunkSeconds;
    context
      .suspend(boundary)
      .then(() => scheduleThrough(session, link, boundary + chunkSeconds))
      .then(() => context.resume())
      .catch(fail);
  }
  const rendered = await Promise.race([context.startRendering(), failure]);
  await Promise.race([delivered, failure]);
  session.dispose();
  return Array.from({ length: rendered.numberOfChannels }, (_, channel) => rendered.getChannelData(channel));
}
