/** Live engine: lookahead scheduling plus iOS-safe unlock, resume and suspend. */
import type { OfflineOptions, Score } from "../../spec/api.ts";
import type { EngineAssets } from "./loader.ts";
import { renderScore } from "./offline.ts";
import { Session, type SessionParts } from "./session.ts";

const SCHEDULE_INTERVAL_MILLISECONDS = 25;
const VISIBLE_HORIZON_SECONDS = 0.2;
const HIDDEN_HORIZON_SECONDS = 1.5;
const GESTURE_EVENTS = ["pointerdown", "touchend", "keydown"] as const;

/** Whether the engine created its context and so must close it. */
export enum ContextOwnership {
  Owned,
  Borrowed,
}

/** What the user last asked the context to do. */
enum Wish {
  Suspended,
  Running,
}

interface AudioSessionNavigator {
  audioSession?: { type: string };
}

/** Asks iOS for media playback, which ignores the mute switch. */
function preferPlaybackSession(): void {
  const audioSession = (globalThis.navigator as AudioSessionNavigator | undefined)?.audioSession;
  if (audioSession) audioSession.type = "playback";
}

/** Plays one silent sample; iOS needs this inside the gesture. */
function playSilence(context: AudioContext): void {
  const source = context.createBufferSource();
  source.buffer = context.createBuffer(1, 1, context.sampleRate);
  source.connect(context.destination);
  source.start(0);
}

/** Engine on a real AudioContext, driven by a lookahead timer. */
export class LiveEngine extends Session {
  private readonly audioContext: AudioContext;
  private readonly assets: EngineAssets;
  private readonly ownership: ContextOwnership;
  private readonly timer: ReturnType<typeof setInterval>;
  private wish = Wish.Suspended;
  private readonly onVisibility = () => this.recoverAfterHidden();
  private readonly onStateChange = () => this.watchInterruption();
  private readonly onGesture = () => {
    this.unlock().catch((failure: unknown) => console.error("Audio unlock failed", failure));
  };

  constructor(parts: SessionParts & { readonly context: AudioContext }, assets: EngineAssets, ownership: ContextOwnership) {
    super(parts);
    this.audioContext = parts.context;
    this.assets = assets;
    this.ownership = ownership;
    this.timer = setInterval(() => this.tick(), SCHEDULE_INTERVAL_MILLISECONDS);
    this.audioContext.addEventListener("statechange", this.onStateChange);
    globalThis.document?.addEventListener("visibilitychange", this.onVisibility);
  }

  get state(): AudioContextState | "interrupted" {
    return this.audioContext.state as AudioContextState | "interrupted";
  }

  async unlock(): Promise<void> {
    preferPlaybackSession();
    playSilence(this.audioContext);
    await this.resume();
  }

  async resume(): Promise<void> {
    this.wish = Wish.Running;
    if (this.audioContext.state !== "running") await this.audioContext.resume();
    this.tick();
  }

  async suspend(): Promise<void> {
    this.wish = Wish.Suspended;
    await this.audioContext.suspend();
  }

  renderOffline(score: Score, options: OfflineOptions): Promise<Float32Array[]> {
    return renderScore(this.assets, score, options, this.audioContext.sampleRate);
  }

  dispose(): void {
    super.dispose();
    clearInterval(this.timer);
    this.audioContext.removeEventListener("statechange", this.onStateChange);
    globalThis.document?.removeEventListener("visibilitychange", this.onVisibility);
    this.disarmGesture();
    if (this.ownership === ContextOwnership.Owned) this.audioContext.close().catch((failure: unknown) => console.error(failure));
  }

  /** Runs transport callbacks inside the lookahead horizon. */
  private tick(): void {
    const hidden = globalThis.document?.hidden ?? false;
    const horizon = hidden ? HIDDEN_HORIZON_SECONDS : VISIBLE_HORIZON_SECONDS;
    this.transport.advance(this.audioContext.currentTime + horizon);
    this.flush();
  }

  private recoverAfterHidden(): void {
    if (globalThis.document?.hidden || this.wish !== Wish.Running) return;
    if (this.audioContext.state === "running") return;
    this.audioContext.resume().catch(() => this.armGesture());
  }

  /** After an interruption, the next tap or key resumes playback. */
  private watchInterruption(): void {
    const stopped = this.audioContext.state !== "running" && this.audioContext.state !== "closed";
    if (stopped && this.wish === Wish.Running) this.armGesture();
    else this.disarmGesture();
  }

  private armGesture(): void {
    for (const name of GESTURE_EVENTS) globalThis.document?.addEventListener(name, this.onGesture, { capture: true });
  }

  private disarmGesture(): void {
    for (const name of GESTURE_EVENTS) globalThis.document?.removeEventListener(name, this.onGesture, { capture: true });
  }
}
