// Best-practice patch rewrite and runtime wrapper for the five engines.
// Numbers follow docs/research/sound-engineering.md; capabilities follow docs/engine-reviews.md.
import { NOISE_FLOOR_DB, startNoiseFloor } from "./noise-floor.js";

/** Engine capabilities; trims in dB are measured on the test song. */
const ENGINES = {
  "0-original": {
    readsMaster: false, forcedHighpass: 120, hasCeiling: false, nativeMakeup: true, flatQ: 0,
    linearQ: false, oversamplesDistortion: false, sparesVoices: false, fadesOnDispose: false, pinkNoiseTrim: 0, loudnessTrim: 6, faderOffset: 14,
  },
  "1-live-hardened": {
    readsMaster: true, forcedHighpass: 0, hasCeiling: true, nativeMakeup: false, flatQ: undefined,
    linearQ: false, oversamplesDistortion: true, sparesVoices: false, fadesOnDispose: true, pinkNoiseTrim: 0, loudnessTrim: -0.8, faderOffset: 0,
  },
  "2-baked-notes": {
    readsMaster: true, forcedHighpass: 0, hasCeiling: false, nativeMakeup: true, flatQ: -3.01,
    linearQ: false, oversamplesDistortion: false, sparesVoices: false, fadesOnDispose: false, pinkNoiseTrim: 0, loudnessTrim: 4.6, faderOffset: 0,
  },
  "3-stem-loops": {
    readsMaster: true, forcedHighpass: 0, hasCeiling: false, nativeMakeup: true, flatQ: -3.01,
    linearQ: false, oversamplesDistortion: false, sparesVoices: false, fadesOnDispose: false, pinkNoiseTrim: -6, loudnessTrim: 5.5, faderOffset: 0,
  },
  "5-wasm-worklet": {
    readsMaster: true, forcedHighpass: 0, hasCeiling: false, nativeMakeup: false, flatQ: undefined,
    linearQ: true, oversamplesDistortion: false, sparesVoices: true, fadesOnDispose: false, pinkNoiseTrim: 0, loudnessTrim: -0.7, faderOffset: 0,
  },
};

/** Per-role high-pass (Hz), envelope floors (s), and low-end mono flag. */
const ROLES = {
  bass: { highpass: 30, attack: 0.01, release: 0.08, isLowEnd: true },
  kick: { highpass: 30, attack: 0.001, release: 0.03, isLowEnd: true },
  harmony: { highpass: 120, attack: 0.003, release: 0.03, isLowEnd: false },
  lead: { highpass: 150, attack: 0.003, release: 0.03, isLowEnd: false },
  counter: { highpass: 150, attack: 0.003, release: 0.03, isLowEnd: false },
  accent: { highpass: 200, attack: 0.003, release: 0.03, isLowEnd: false },
  snare: { highpass: 80, attack: 0.001, release: 0.03, isLowEnd: false },
  hat: { highpass: 300, attack: 0.001, release: 0.03, isLowEnd: false },
  perc: { highpass: 60, attack: 0.001, release: 0.03, isLowEnd: false },
};

const BUS_ROLE = { highpass: 0, attack: 0, release: 0, isLowEnd: false };
const PASS_TYPES = ["lowpass", "highpass"];
const CEILING_DB = -1.5;
const MAX_FEEDBACK = 0.6;
const MAX_WIDTH = 0.7;
const SPARE_VOICES = 2;
const FADE_SECONDS = 0.05;
const FADE_WAIT_MILLISECONDS = 100;
const SILENT_DB = -100;

const capabilityOf = (engine) => {
  const capability = ENGINES[engine];
  if (capability === undefined) throw new Error(`unknown engine "${engine}"; expected one of ${Object.keys(ENGINES).join(", ")}`);
  return capability;
};

const roleOf = (roles, id) => {
  const rule = ROLES[roles[id]];
  if (rule === undefined) throw new Error(`instrument "${id}" has role "${roles[id]}"; expected one of ${Object.keys(ROLES).join(", ")}`);
  return rule;
};

const passFilter = (type, frequency, rolloff) => ({ type: "filter", filter: { type, frequency, rolloff } });

// Spec lacks gain effects; 10 Hz shelf is flat above 30 Hz.
const gainStage = (decibels) => ({ type: "filter", filter: { type: "highshelf", frequency: 10, gain: decibels } });

const isFilterOf = (effect, type) => effect.type === "filter" && effect.filter.type === type;

const decibels = (value) => `${Number(value.toFixed(1))} dB`;

const fixDistortion = (effect, { capability, note }) => {
  const isAliasing = (effect.oversample ?? "none") === "none" && !capability.oversamplesDistortion;
  if (!isAliasing) return [effect];
  note("distortion oversampled 4x");
  return [{ ...effect, oversample: "4x" }];
};

const fixCompressor = (effect, { capability, note }) => {
  if (!capability.nativeMakeup) return [effect];
  const makeup = -0.6 * effect.threshold * (1 - 1 / effect.ratio);
  note(`compressor auto makeup ${decibels(makeup)} cancelled`);
  return [effect, gainStage(-makeup)];
};

const fixChebyshev = (effect, { note }) => {
  if (effect.order % 2 !== 0) return [effect];
  note("DC blocker after even-order chebyshev");
  return [effect, passFilter("highpass", 20, -12)];
};

const clampFeedback = (effect, { note }) => {
  if (effect.feedback <= MAX_FEEDBACK) return [effect];
  note(`delay feedback ${effect.feedback} -> ${MAX_FEEDBACK}`);
  return [{ ...effect, feedback: MAX_FEEDBACK }];
};

const fixWidener = (effect, { rule, note }) => {
  const limit = rule.isLowEnd ? 0.5 : MAX_WIDTH;
  if (effect.width <= limit) return [effect];
  note(`widener width ${effect.width} -> ${limit}`);
  return [{ ...effect, width: limit }];
};

const fixChorus = (effect, { rule, note }) => {
  if (!rule.isLowEnd || effect.spread === 0) return [effect];
  note("chorus made mono (spread 0)");
  return [{ ...effect, spread: 0 }];
};

const EFFECT_FIXES = {
  distortion: fixDistortion,
  compressor: fixCompressor,
  chebyshev: fixChebyshev,
  feedbackdelay: clampFeedback,
  pingpong: clampFeedback,
  widener: fixWidener,
  chorus: fixChorus,
};

const fixEffects = (effects, setting) => (effects ?? []).flatMap((effect) => EFFECT_FIXES[effect.type]?.(effect, setting) ?? [effect]);

// Engines 0, 2, 3 default Q 1 dB; engine 5 reads linear.
const insertFilter = (filter, capability) => {
  if (!PASS_TYPES.includes(filter.type)) return filter;
  if (filter.Q !== undefined) return capability.linearQ ? { ...filter, Q: 10 ** (filter.Q / 20) } : filter;
  return capability.flatQ === undefined ? filter : { ...filter, Q: capability.flatQ };
};

const sourceFilter = (filter, capability) => {
  const isConverted = capability.linearQ && PASS_TYPES.includes(filter.type) && filter.Q !== undefined;
  return isConverted ? { ...filter, Q: 10 ** (filter.Q / 20) } : filter;
};

const withEngineQ = (effects, capability) =>
  effects.map((effect) => (effect.type === "filter" ? { ...effect, filter: insertFilter(effect.filter, capability) } : effect));

const raiseEnvelope = (envelope, rule) =>
  ({ ...envelope, attack: Math.max(envelope.attack, rule.attack), release: Math.max(envelope.release, rule.release) });

const monoVoice = (voice, rule, capability) =>
  ({ ...voice, envelope: raiseEnvelope(voice.envelope, rule), filter: sourceFilter(voice.filter, capability) });

const fixSource = (source, rule, capability) => {
  if (source.kind === "sampler") return { ...source, attack: Math.max(source.attack, rule.attack), release: Math.max(source.release, rule.release) };
  if (source.kind === "duo") return { ...source, voices: source.voices.map((voice) => monoVoice(voice, rule, capability)) };
  if (source.kind === "mono") return { ...source, ...monoVoice(source, rule, capability) };
  return { ...source, envelope: raiseEnvelope(source.envelope, rule) };
};

const fixPolyphony = (instrument, { capability, note }) => {
  const isPolyphonic = (instrument.polyphony ?? 1) > 1 && !["mono", "duo"].includes(instrument.source.kind);
  if (!isPolyphonic || capability.sparesVoices) return instrument.polyphony;
  note(`polyphony ${instrument.polyphony} -> ${instrument.polyphony + SPARE_VOICES}`);
  return instrument.polyphony + SPARE_VOICES;
};

const roleHighpass = (effects, { rule, capability, note }) => {
  const isCovered = Math.max(capability.forcedHighpass, ...effects.filter((effect) => isFilterOf(effect, "highpass")).map((effect) => effect.filter.frequency)) >= rule.highpass;
  if (isCovered) return [];
  note(`HPF ${rule.highpass} Hz`);
  return [passFilter("highpass", rule.highpass, -12)];
};

const partTrim = (instrument, { capability, masterLevel, note }) => {
  const isPink = instrument.source.kind === "noise" && instrument.source.noise === "pink";
  const level = (capability.readsMaster ? 0 : masterLevel) + (isPink ? capability.pinkNoiseTrim : 0);
  if (level === 0) return [];
  note(`level trim ${decibels(level)}`);
  return [gainStage(level)];
};

const fixInstrument = (instrument, setting) => {
  const source = fixSource(instrument.source, setting.rule, setting.capability);
  if (JSON.stringify(source) !== JSON.stringify(instrument.source)) setting.note("source envelope floors or Q units fixed");
  const effects = fixEffects(instrument.effects, setting);
  const tail = [...roleHighpass(effects, setting), ...partTrim(instrument, setting)];
  const polyphony = fixPolyphony(instrument, setting);
  return { ...instrument, source, polyphony, effects: withEngineQ([...effects, ...tail], setting.capability) };
};

const fixReturns = (effects, setting) => {
  const fixed = fixEffects(effects, setting);
  const highpass = fixed.some((effect) => isFilterOf(effect, "highpass")) ? [] : [passFilter("highpass", 400, -12)];
  const lowpass = fixed.some((effect) => isFilterOf(effect, "lowpass")) ? [] : [passFilter("lowpass", 8000, -12)];
  if (highpass.length + lowpass.length > 0) setting.note("filters added (HPF 400 Hz, LPF 8 kHz)");
  return withEngineQ([...fixed, ...highpass, ...lowpass], setting.capability);
};

// Insert after the first filter so filter ramps keep their target.
const insertAfterFirstFilter = (effects, inserts) => {
  const index = effects.findIndex((effect) => effect.type === "filter");
  if (index === -1) return [...inserts, ...effects];
  return [...effects.slice(0, index + 1), ...inserts, ...effects.slice(index + 1)];
};

const withCeiling = (effects, { capability, note }) => {
  if (capability.hasCeiling) return effects;
  const last = effects[effects.length - 1];
  if (last?.type !== "limiter") {
    note(`limiter ${CEILING_DB} dBTP added`);
    return [...effects, { type: "limiter", threshold: CEILING_DB }];
  }
  if (last.threshold <= CEILING_DB) return effects;
  note(`limiter ${last.threshold} -> ${CEILING_DB} dBTP`);
  return [...effects.slice(0, -1), { ...last, threshold: CEILING_DB }];
};

const fixMaster = (master, setting) => {
  const fixed = fixEffects(master.effects, setting);
  const hasRumbleGuard = fixed.some((effect) => isFilterOf(effect, "highpass"));
  if (!hasRumbleGuard) setting.note("rumble guard HPF 25 Hz added");
  const rumble = hasRumbleGuard ? [] : [passFilter("highpass", 25, -24)];
  const trim = setting.masterLevel === 0 ? [] : [gainStage(setting.masterLevel)];
  setting.note(`level ${decibels(setting.masterLevel)} moved before the ceiling`);
  const effects = withCeiling(insertAfterFirstFilter(fixed, [...rumble, ...trim]), setting);
  return { volume: 0, effects: withEngineQ(effects, setting.capability) };
};

const engineNotes = (engine, capability) => [
  ...(capability.readsMaster ? [] : [`skipped: ${engine} ignores master and return chains; no ceiling possible`]),
  ...(capability.forcedHighpass > 0 ? [`skipped: ${engine} forces a ${capability.forcedHighpass} Hz HPF on every part`] : []),
  ...(capability.hasCeiling ? [`skipped: ${engine} has its own ceiling`] : []),
  ...(capability.sparesVoices ? [`skipped: ${engine} already adds ${SPARE_VOICES} spare voices`] : []),
  `output: noise floor ${NOISE_FLOOR_DB} dBFS added by the wrapper`,
  "skipped: chebyshev oversampling and mono-below-120 Hz are not expressible",
];

/** Returns a new patch with best practices this engine honours. */
export function applyBestPractice(patch, { engine, roles }) {
  const capability = capabilityOf(engine);
  const notes = [];
  const noteFor = (label) => (text) => notes.push(`${label}: ${text}`);
  const masterLevel = (patch.master.volume ?? 0) + capability.loudnessTrim;
  const instruments = patch.instruments.map((instrument) => {
    const rule = roleOf(roles, instrument.id);
    return fixInstrument(instrument, { rule, capability, masterLevel, note: noteFor(instrument.id) });
  });
  if (!capability.readsMaster) return { patch: { ...patch, instruments }, notes: [...notes, ...engineNotes(engine, capability)] };
  const busSetting = (label) => ({ rule: BUS_ROLE, capability, masterLevel, note: noteFor(label) });
  const returnEffects = fixReturns(patch.reverb.returnEffects, busSetting("reverb return"));
  const master = fixMaster(patch.master, busSetting("master"));
  const fixedPatch = { ...patch, instruments, reverb: { ...patch.reverb, returnEffects }, master };
  return { patch: fixedPatch, notes: [...notes, ...engineNotes(engine, capability)] };
}

/** Wraps an engine with a noise floor and faded suspend and dispose. */
export function wrapEngine(engine, { engine: name }) {
  const capability = capabilityOf(name);
  const stopNoise = startNoiseFloor(engine.context);
  const fader = { level: 0, isMuted: false };
  const moveFader = (level, duration, time) => engine.ramp("volume", level + capability.faderOffset, duration, time);
  const fadeTo = (level) => moveFader(level, FADE_SECONDS, engine.context.currentTime);
  if (capability.faderOffset !== 0) moveFader(0, 0, engine.context.currentTime);
  const fadeIn = () => {
    if (!fader.isMuted) return;
    fader.isMuted = false;
    fadeTo(fader.level);
  };
  const fadeOut = () => new Promise((done) => {
    fader.isMuted = true;
    fadeTo(SILENT_DB);
    setTimeout(done, FADE_WAIT_MILLISECONDS);
  });
  const ramp = (...request) => {
    const [target, value, duration, time, instrumentId] = request;
    const isFader = target === "volume" && instrumentId === undefined;
    if (!isFader) return engine.ramp(...request);
    fader.level = value;
    if (!fader.isMuted) moveFader(value, duration, time);
  };
  return {
    get context() { return engine.context; },
    get transport() { return engine.transport; },
    get state() { return engine.state; },
    get now() { return engine.now; },
    instrument: (id) => engine.instrument(id),
    ramp,
    unlock: async () => {
      await engine.unlock();
      fadeIn();
    },
    resume: async () => {
      await engine.resume();
      fadeIn();
    },
    suspend: async () => {
      if (engine.state === "running") await fadeOut();
      await engine.suspend();
    },
    renderOffline: (score, options) => engine.renderOffline((inner) => score(wrapEngine(inner, { engine: name })), options),
    dispose: () => {
      const finish = () => { stopNoise(); engine.dispose(); };
      if (capability.fadesOnDispose || engine.state !== "running") return finish();
      fadeOut().then(finish);
    },
  };
}
