/** Event records shared with the DSP core: eight numbers each. */
import type { RampTarget } from "../../../spec/api.ts";

/** Event kinds, in the DSP core's numbering. */
export enum EventType {
  NoteOn = 1,
  NoteOff = 2,
  ReleaseAll = 3,
  Ramp = 4,
  Tempo = 5,
  CancelTag = 6,
  CancelAfter = 7,
}

/** Ramp target codes, in the DSP core's numbering. */
export const RAMP_TARGET_CODES: Readonly<Record<RampTarget, number>> = {
  volume: 0,
  pan: 1,
  reverbSend: 2,
  filterFrequency: 3,
};

/** Instrument index meaning the master strip. */
export const MASTER_INDEX = -1;

/** One event before encoding; unused fields default to zero. */
export interface EventRecord {
  readonly type: EventType;
  readonly time: number;
  readonly instrument?: number;
  readonly noteId?: number;
  readonly pitch?: number;
  readonly value?: number;
  readonly duration?: number;
  readonly tag?: number;
}

/** Appends one record's eight numbers to a batch. */
export function encodeEvent(record: EventRecord, batch: number[]): void {
  batch.push(
    record.type,
    record.instrument ?? MASTER_INDEX,
    record.time,
    record.noteId ?? 0,
    record.pitch ?? 0,
    record.value ?? 0,
    record.duration ?? 0,
    record.tag ?? 0,
  );
}
