/** Beat-based transport that runs callbacks ahead with exact audio times. */
import type { Time, Transport } from "../../spec/api.ts";
import { EventType, type EventRecord } from "./core/events.ts";
import { parseTime, partsToBeats } from "./core/notation.ts";

/** What the transport needs from its engine. */
export interface TransportHost {
  /** Audio time new events default to. */
  now(): number;
  /** Queues an event for the DSP core. */
  post(record: EventRecord): void;
}

type TransportState = Transport["state"];

interface ScheduledCallback {
  readonly id: number;
  readonly callback: (time: number) => void;
  readonly startBeat: number;
  readonly intervalBeats: number;
  readonly endBeat: number;
  nextBeat: number;
}

/** Transport clock in quarter-note beats, anchored to audio time. */
export class BeatTransport implements Transport {
  private beatsPerMinute = 120;
  private beatsPerMeasure = 4;
  private status: TransportState = "stopped";
  private anchorTime = 0;
  private anchorBeat = 0;
  private pausedBeat = 0;
  private dispatchedBeat = 0;
  private nextId = 1;
  private readonly callbacks = new Map<number, ScheduledCallback>();
  private readonly host: TransportHost;
  /** Id of the callback running now; events it posts carry it. */
  currentTag = 0;

  constructor(host: TransportHost) {
    this.host = host;
  }

  get bpm(): number {
    return this.beatsPerMinute;
  }

  set bpm(value: number) {
    if (!(value > 0)) throw new Error(`bpm must be positive, got ${value}`);
    this.reanchor();
    this.beatsPerMinute = value;
    this.postTempo();
  }

  get timeSignature(): number {
    return this.beatsPerMeasure;
  }

  set timeSignature(value: number) {
    if (!(value > 0)) throw new Error(`timeSignature must be positive, got ${value}`);
    this.beatsPerMeasure = value;
    this.postTempo();
  }

  get state(): TransportState {
    return this.status;
  }

  get seconds(): number {
    return (this.currentBeat() * 60) / this.beatsPerMinute;
  }

  start(time?: number): void {
    const startTime = time ?? this.host.now();
    this.anchorBeat = this.status === "paused" ? this.pausedBeat : 0;
    this.anchorTime = startTime;
    this.dispatchedBeat = this.anchorBeat;
    this.status = "started";
    this.callbacks.forEach((scheduled) => {
      scheduled.nextBeat = firstOccurrence(scheduled, this.anchorBeat);
    });
  }

  stop(time?: number): void {
    const stopTime = time ?? this.host.now();
    this.status = "stopped";
    this.pausedBeat = 0;
    this.host.post({ type: EventType.CancelAfter, time: stopTime });
  }

  pause(time?: number): void {
    const pauseTime = time ?? this.host.now();
    this.pausedBeat = this.beatAt(pauseTime);
    this.status = "paused";
    this.host.post({ type: EventType.CancelAfter, time: pauseTime });
  }

  scheduleRepeat(callback: (time: number) => void, interval: Time, start: Time = 0, duration?: Time): number {
    const intervalBeats = this.toBeats(interval);
    if (!(intervalBeats > 0)) throw new Error(`Repeat interval must be positive, got "${interval}"`);
    const startBeat = this.toBeats(start);
    const endBeat = duration === undefined ? Infinity : startBeat + this.toBeats(duration);
    return this.add({ callback, startBeat, intervalBeats, endBeat });
  }

  scheduleOnce(callback: (time: number) => void, time: Time): number {
    const startBeat = this.toBeats(time);
    return this.add({ callback, startBeat, intervalBeats: 0, endBeat: startBeat + 1e-9 });
  }

  cancel(eventId: number): void {
    if (!this.callbacks.delete(eventId)) return;
    this.host.post({ type: EventType.CancelTag, time: this.host.now(), tag: eventId });
  }

  toSeconds(time: Time): number {
    if (typeof time === "number") return time;
    return (this.toBeats(time) * 60) / this.beatsPerMinute;
  }

  /** Runs every callback due before an audio time, in time order. */
  advance(untilTime: number): void {
    if (this.status !== "started") return;
    const untilBeat = this.beatAt(untilTime);
    for (let due = this.earliestBefore(untilBeat); due; due = this.earliestBefore(untilBeat)) {
      const beat = due.nextBeat;
      due.nextBeat = beat + due.intervalBeats < due.endBeat && due.intervalBeats > 0 ? beat + due.intervalBeats : Infinity;
      this.run(due, this.timeAt(beat));
    }
    this.dispatchedBeat = Math.max(this.dispatchedBeat, untilBeat);
  }

  private run(scheduled: ScheduledCallback, time: number): void {
    this.currentTag = scheduled.id;
    try {
      scheduled.callback(time);
    } finally {
      this.currentTag = 0;
    }
  }

  private add(fields: Omit<ScheduledCallback, "id" | "nextBeat">): number {
    const id = this.nextId;
    this.nextId += 1;
    const scheduled: ScheduledCallback = { ...fields, id, nextBeat: 0 };
    scheduled.nextBeat = firstOccurrence(scheduled, this.dispatchedBeat);
    this.callbacks.set(id, scheduled);
    return id;
  }

  private earliestBefore(untilBeat: number): ScheduledCallback | undefined {
    let earliest: ScheduledCallback | undefined;
    for (const scheduled of this.callbacks.values()) {
      const isDue = scheduled.nextBeat < untilBeat;
      if (isDue && (!earliest || scheduled.nextBeat < earliest.nextBeat)) earliest = scheduled;
    }
    return earliest;
  }

  private toBeats(time: Time): number {
    return partsToBeats(parseTime(time), this.beatsPerMinute, this.beatsPerMeasure);
  }

  private beatAt(time: number): number {
    return this.anchorBeat + ((time - this.anchorTime) * this.beatsPerMinute) / 60;
  }

  private timeAt(beat: number): number {
    return this.anchorTime + ((beat - this.anchorBeat) * 60) / this.beatsPerMinute;
  }

  private currentBeat(): number {
    if (this.status === "paused") return this.pausedBeat;
    if (this.status === "stopped") return 0;
    return Math.max(this.beatAt(this.host.now()), this.anchorBeat);
  }

  private reanchor(): void {
    if (this.status !== "started") return;
    const now = this.host.now();
    this.anchorBeat = this.beatAt(now);
    this.anchorTime = now;
  }

  private postTempo(): void {
    this.host.post({ type: EventType.Tempo, time: this.host.now(), value: this.beatsPerMinute, pitch: this.beatsPerMeasure });
  }
}

/** First beat at or after a point, or infinity when none remains. */
function firstOccurrence(scheduled: ScheduledCallback, fromBeat: number): number {
  if (scheduled.intervalBeats <= 0) return scheduled.startBeat >= fromBeat - 1e-9 ? scheduled.startBeat : Infinity;
  const skipped = Math.max(0, Math.ceil((fromBeat - scheduled.startBeat) / scheduled.intervalBeats - 1e-9));
  const beat = scheduled.startBeat + skipped * scheduled.intervalBeats;
  return beat < scheduled.endBeat ? beat : Infinity;
}
