/** Parses tempo notation and note names into numbers. */
import type { Note, Time } from "../../../spec/api.ts";

/** A duration split into absolute seconds, beats and measures. */
export interface TimeParts {
  readonly seconds: number;
  readonly beats: number;
  readonly measures: number;
}

const NOTE_VALUE = /^(\d+)([nt])(\.?)$/;
const MEASURES = /^(\d+(?:\.\d+)?)m$/;
const BARS_BEATS = /^(\d+):(\d+(?:\.\d+)?)(?::(\d+(?:\.\d+)?))?$/;
const NUMBER = /^-?\d+(?:\.\d+)?$/;
const NOTE_NAME = /^([A-Ga-g])(#{1,2}|b{1,2})?(-?\d+)$/;
const SEMITONES: Record<string, number> = { c: 0, d: 2, e: 4, f: 5, g: 7, a: 9, b: 11 };

function noteValueParts(match: RegExpMatchArray): TimeParts {
  const division = Number(match[1]);
  const tripletScale = match[2] === "t" ? 2 / 3 : 1;
  const dotScale = match[3] === "." ? 1.5 : 1;
  return { seconds: 0, beats: (4 / division) * tripletScale * dotScale, measures: 0 };
}

function barsBeatsParts(match: RegExpMatchArray): TimeParts {
  const sixteenths = Number(match[3] ?? 0);
  return { seconds: 0, beats: Number(match[2]) + sixteenths / 4, measures: Number(match[1]) };
}

/** Splits a time into seconds, beats and measures; fails on unknown notation. */
export function parseTime(time: Time): TimeParts {
  if (typeof time === "number") return { seconds: time, beats: 0, measures: 0 };
  const text = time.trim();
  const noteValue = text.match(NOTE_VALUE);
  if (noteValue) return noteValueParts(noteValue);
  const measures = text.match(MEASURES);
  if (measures) return { seconds: 0, beats: 0, measures: Number(measures[1]) };
  const barsBeats = text.match(BARS_BEATS);
  if (barsBeats) return barsBeatsParts(barsBeats);
  if (NUMBER.test(text)) return { seconds: Number(text), beats: 0, measures: 0 };
  throw new Error(`Unknown time notation "${time}"`);
}

/** Total beats of a time at a tempo and meter. */
export function partsToBeats(parts: TimeParts, beatsPerMinute: number, beatsPerMeasure: number): number {
  return parts.beats + parts.measures * beatsPerMeasure + (parts.seconds * beatsPerMinute) / 60;
}

/** MIDI number of a note name like "F#2"; numbers pass through. */
export function noteToMidi(note: Note): number {
  if (typeof note === "number") return note;
  const match = note.trim().match(NOTE_NAME);
  if (!match) throw new Error(`Unknown note "${note}"`);
  const accidental = match[2] ?? "";
  const shift = accidental.startsWith("#") ? accidental.length : -accidental.length;
  return SEMITONES[match[1].toLowerCase()] + shift + (Number(match[3]) + 1) * 12;
}
