/** Main-thread side of the worklet port: sends, syncs, chunks and errors. */
import type { FromProcessor, ToProcessor } from "./protocol.ts";

type ChunkMessage = Extract<FromProcessor, { type: "chunk" }>;

interface Waiter {
  readonly resolve: () => void;
  readonly reject: (failure: Error) => void;
}

/** Typed wrapper around one processor's message port. */
export class WorkletLink {
  private readonly port: MessagePort;
  private readonly waiters = new Map<number, Waiter>();
  private nextSyncId = 1;
  private failure: Error | null = null;
  private chunkListener: ((chunk: ChunkMessage) => void) | null = null;

  constructor(node: AudioWorkletNode) {
    this.port = node.port;
    this.port.onmessage = (event: MessageEvent<FromProcessor>) => this.receive(event.data);
    node.onprocessorerror = () => this.fail(new Error("The DSP worklet processor crashed"));
  }

  /** Posts a message, transferring any listed buffers. */
  send(message: ToProcessor, transfer: Transferable[] = []): void {
    if (this.failure) throw this.failure;
    this.port.postMessage(message, transfer);
  }

  /** Resolves once the processor has handled every earlier message. */
  sync(): Promise<void> {
    if (this.failure) return Promise.reject(this.failure);
    const id = this.nextSyncId;
    this.nextSyncId += 1;
    const settled = new Promise<void>((resolve, reject) => this.waiters.set(id, { resolve, reject }));
    this.send({ type: "sync", id });
    return settled;
  }

  /** Calls the listener for each rendered chunk the processor posts. */
  listenForChunks(listener: (chunk: ChunkMessage) => void): void {
    this.chunkListener = listener;
  }

  private receive(message: FromProcessor): void {
    if (message.type === "chunk") {
      this.chunkListener?.(message);
      return;
    }
    if (message.type === "error") {
      this.fail(new Error(message.message));
      return;
    }
    this.waiters.get(message.id)?.resolve();
    this.waiters.delete(message.id);
  }

  private fail(failure: Error): void {
    this.failure = failure;
    if (this.waiters.size === 0) console.error(failure);
    this.waiters.forEach((waiter) => waiter.reject(failure));
    this.waiters.clear();
  }
}
