/** Compiles a Patch into the flat number program the DSP core reads. */
import type { EffectSpec, EnvelopeSpec, FilterSpec, InstrumentSpec, OscillatorSpec, Patch, SourceSpec, Time } from "../../../spec/api.ts";
import { noteToMidi, parseTime } from "./notation.ts";
import { type TierSettings } from "./tiers.ts";

/** Program format version, checked by the DSP core. */
const FORMAT_VERSION = 1;

/** One recording a sampler instrument needs loaded. */
export interface RecordingRequest {
  readonly instrumentIndex: number;
  readonly midi: number;
  readonly url: string;
}

/** A compiled patch plus what the shell needs to drive it. */
export interface CompiledPatch {
  readonly program: Float64Array;
  readonly instrumentIds: readonly string[];
  readonly filterTargets: ReadonlySet<string>;
  readonly masterHasFilter: boolean;
  readonly recordings: readonly RecordingRequest[];
}

const WAVEFORMS = ["sine", "triangle", "sawtooth", "square", "pulse", "fatsawtooth"];
const FILTER_TYPES = ["lowpass", "highpass", "bandpass", "peaking", "highshelf", "lowshelf"];
const NOISE_COLORS = ["white", "pink", "brown"];
const OVERSAMPLE_FACTORS: Record<string, number> = { none: 1, "2x": 2, "4x": 4 };
const BUTTERWORTH_FOURTH_ORDER = [0.5411961, 1.3065630];

function codeOf(list: readonly string[], name: string, what: string): number {
  const code = list.indexOf(name);
  if (code < 0) throw new Error(`Unknown ${what} "${name}"`);
  return code;
}

function oscillator(spec: OscillatorSpec): number[] {
  const waveform = codeOf(WAVEFORMS, spec.type, "oscillator type");
  return [waveform, spec.width ?? 0.5, spec.count ?? 3, spec.spread ?? 20, spec.detune ?? 0];
}

function envelope(spec: EnvelopeSpec): number[] {
  return [spec.attack, spec.decay, spec.sustain, spec.release];
}

function defaultQualities(type: string, stages: number): number[] {
  if (type === "bandpass" || type === "peaking") return [1, 1];
  if (stages === 2) return BUTTERWORTH_FOURTH_ORDER;
  return [Math.SQRT1_2, Math.SQRT1_2];
}

function filter(spec: FilterSpec): number[] {
  const type = codeOf(FILTER_TYPES, spec.type, "filter type");
  const cascades = ["lowpass", "highpass", "bandpass"].includes(spec.type);
  const stages = cascades && spec.rolloff === -24 ? 2 : 1;
  const qualities = spec.Q === undefined ? defaultQualities(spec.type, stages) : [spec.Q, spec.Q];
  return [type, spec.frequency, spec.gain ?? 0, stages, ...qualities];
}

function timeParts(time: Time): number[] {
  const parts = parseTime(time);
  return [parts.seconds, parts.beats, parts.measures];
}

function rate(frequency: Time): number[] {
  if (typeof frequency === "number") return [frequency, 0, 0];
  const parts = parseTime(frequency);
  if (parts.seconds > 0) return [parts.seconds, 0, 0];
  return [0, parts.beats, parts.measures];
}

type MonoFields = Omit<Extract<SourceSpec, { kind: "mono" }>, "kind">;

function monoPart(spec: MonoFields): number[] {
  const sweep = spec.filterEnvelope;
  return [...oscillator(spec.oscillator), ...envelope(spec.envelope), ...filter(spec.filter), ...envelope(sweep), sweep.baseFrequency, sweep.octaves];
}

const SOURCE_ENCODERS: { [Kind in SourceSpec["kind"]]: (spec: Extract<SourceSpec, { kind: Kind }>) => number[] } = {
  synth: (spec) => [0, ...oscillator(spec.oscillator), ...envelope(spec.envelope)],
  mono: (spec) => [1, ...monoPart(spec), spec.portamento ?? 0],
  fm: (spec) => [2, ...oscillator(spec.oscillator), ...oscillator(spec.modulator), spec.harmonicity, spec.modulationIndex, ...envelope(spec.envelope), ...envelope(spec.modulationEnvelope)],
  duo: (spec) => [3, ...monoPart(spec.voices[0]), ...monoPart(spec.voices[1]), spec.harmonicity, spec.vibratoRate, spec.vibratoAmount, spec.portamento ?? 0],
  membrane: (spec) => [4, ...oscillator(spec.oscillator), ...envelope(spec.envelope), spec.pitchDecay, spec.octaves],
  noise: (spec) => [5, codeOf(NOISE_COLORS, spec.noise, "noise color"), ...envelope(spec.envelope)],
  sampler: (spec) => [6, spec.attack, spec.release],
};

const EFFECT_ENCODERS: { [Type in EffectSpec["type"]]: (spec: Extract<EffectSpec, { type: Type }>) => number[] } = {
  filter: (spec) => [0, ...filter(spec.filter)],
  autofilter: (spec) => [1, ...rate(spec.frequency), spec.baseFrequency, spec.octaves, spec.depth, spec.wet ?? 1, 0, spec.baseFrequency, 0, 1, 1, 1],
  compressor: (spec) => [2, spec.threshold, spec.ratio, spec.attack, spec.release, spec.knee],
  limiter: (spec) => [3, spec.threshold],
  distortion: (spec) => [4, spec.amount, OVERSAMPLE_FACTORS[spec.oversample ?? "none"] ?? 1, spec.wet ?? 1],
  chebyshev: (spec) => [5, spec.order, spec.wet ?? 1],
  chorus: (spec) => [6, spec.frequency, spec.delayTime, spec.depth, spec.spread ?? 180, spec.wet ?? 1],
  tremolo: (spec) => [7, spec.frequency, spec.depth, spec.spread ?? 180, spec.wet ?? 1],
  vibrato: (spec) => [8, spec.frequency, spec.depth, spec.wet ?? 1],
  widener: (spec) => [9, spec.width],
  feedbackdelay: (spec) => [10, ...timeParts(spec.delayTime), spec.feedback, spec.wet ?? 1],
  pingpong: (spec) => [11, ...timeParts(spec.delayTime), spec.feedback, spec.wet ?? 1],
  reverb: (spec) => [12, spec.decay, spec.preDelay, spec.wet ?? 1],
};

function encodeSource(spec: SourceSpec): number[] {
  const encoder = SOURCE_ENCODERS[spec.kind] as ((source: SourceSpec) => number[]) | undefined;
  if (!encoder) throw new Error(`Unknown source kind "${(spec as { kind: string }).kind}"`);
  return encoder(spec);
}

function encodeEffects(effects: readonly EffectSpec[] = []): number[] {
  const encoded = effects.flatMap((effect) => {
    const encoder = EFFECT_ENCODERS[effect.type] as ((spec: EffectSpec) => number[]) | undefined;
    if (!encoder) throw new Error(`Unknown effect type "${(effect as { type: string }).type}"`);
    return encoder(effect);
  });
  return [effects.length, ...encoded];
}

function defaultPolyphony(source: SourceSpec): number {
  return source.kind === "mono" || source.kind === "duo" ? 1 : 8;
}

function encodeInstrument(spec: InstrumentSpec): number[] {
  const polyphony = spec.polyphony ?? defaultPolyphony(spec.source);
  const strip = [spec.volume ?? 0, spec.pan ?? 0, spec.reverbSend ?? 0];
  return [polyphony, ...encodeSource(spec.source), ...strip, ...encodeEffects(spec.effects)];
}

function recordingsOf(patch: Patch): RecordingRequest[] {
  return patch.instruments.flatMap((instrument, instrumentIndex) => {
    if (instrument.source.kind !== "sampler") return [];
    return Object.entries(instrument.source.urls).map(([note, url]) => ({ instrumentIndex, midi: noteToMidi(note), url }));
  });
}

function hasFilter(effects: readonly EffectSpec[] | undefined): boolean {
  return (effects ?? []).some((effect) => effect.type === "filter");
}

/** Validates and flattens a patch for one quality tier. */
export function compilePatch(patch: Patch, tier: TierSettings): CompiledPatch {
  const ids = patch.instruments.map((instrument) => instrument.id);
  const duplicate = ids.find((id, index) => ids.indexOf(id) !== index);
  if (duplicate !== undefined) throw new Error(`Instrument id "${duplicate}" is used twice`);
  const tierFields = [tier.oversampleLimit, tier.voiceLimit, tier.reverbSecondsLimit, tier.shaperOversample, tier.fatCountLimit, tier.controlInterval];
  const program = [
    FORMAT_VERSION,
    ...tierFields,
    patch.instruments.length,
    ...patch.instruments.flatMap(encodeInstrument),
    patch.reverb.roomSize,
    ...encodeEffects(patch.reverb.returnEffects),
    patch.master.volume ?? 0,
    ...encodeEffects(patch.master.effects),
  ];
  return {
    program: Float64Array.from(program),
    instrumentIds: ids,
    filterTargets: new Set(patch.instruments.filter((instrument) => hasFilter(instrument.effects)).map((instrument) => instrument.id)),
    masterHasFilter: hasFilter(patch.master.effects),
    recordings: recordingsOf(patch),
  };
}
