/** Quality tiers that trade sound detail for CPU on weak devices. */

/** Named quality levels; "auto" picks one from the device. */
export type QualityTier = "high" | "medium" | "low";

/** Limits the DSP core applies for a tier. */
export interface TierSettings {
  readonly oversampleLimit: number;
  readonly voiceLimit: number;
  readonly reverbSecondsLimit: number;
  readonly shaperOversample: number;
  readonly fatCountLimit: number;
  readonly controlInterval: number;
}

/** Settings for each tier. */
export const TIERS: Readonly<Record<QualityTier, TierSettings>> = {
  high: { oversampleLimit: 4, voiceLimit: 32, reverbSecondsLimit: 10, shaperOversample: 2, fatCountLimit: 8, controlInterval: 16 },
  medium: { oversampleLimit: 2, voiceLimit: 8, reverbSecondsLimit: 3, shaperOversample: 1, fatCountLimit: 4, controlInterval: 32 },
  low: { oversampleLimit: 1, voiceLimit: 4, reverbSecondsLimit: 1.5, shaperOversample: 1, fatCountLimit: 2, controlInterval: 64 },
};

/** Device facts used to guess a tier. */
export interface DeviceFacts {
  readonly cores: number;
  readonly memoryGigabytes: number;
  readonly isMobile: boolean;
}

/** Picks a tier from device facts. */
export function chooseTier(device: DeviceFacts): QualityTier {
  if (device.cores <= 2 || device.memoryGigabytes <= 2) return "low";
  if (device.isMobile) return "medium";
  return "high";
}
