// Faint white noise under the mix, like a recording's natural floor.
// Bluetooth earbuds popped on perfectly clean synth output; this stops it.

/** Noise floor level in dBFS RMS. */
export const NOISE_FLOOR_DB = -84;

const BUFFER_SECONDS = 4;

// Uniform noise has RMS of its peak over root three.
const fillNoise = (buffer) => {
  const peak = 10 ** (NOISE_FLOOR_DB / 20) * Math.sqrt(3);
  for (let channel = 0; channel < buffer.numberOfChannels; channel += 1) {
    const samples = buffer.getChannelData(channel);
    for (let index = 0; index < samples.length; index += 1) samples[index] = (Math.random() * 2 - 1) * peak;
  }
};

/** Loops stereo noise into a context's output; returns its stop function. */
export function startNoiseFloor(context) {
  const buffer = context.createBuffer(2, Math.round(BUFFER_SECONDS * context.sampleRate), context.sampleRate);
  fillNoise(buffer);
  const source = context.createBufferSource();
  source.buffer = buffer;
  source.loop = true;
  source.connect(context.destination);
  source.start(context.currentTime);
  return () => {
    source.stop();
    source.disconnect();
  };
}
