/** Fetches the WASM core and recordings, and builds DSP worklet nodes. */
import type { CompiledPatch, RecordingRequest } from "./core/program.ts";
import { WorkletLink } from "./link.ts";
import { PROCESSOR_NAME, type ProcessorSetup } from "./protocol.ts";

/** A recording decoded once and reused by every render. */
export interface DecodedRecording {
  readonly instrumentIndex: number;
  readonly midi: number;
  readonly rate: number;
  readonly channels: Float32Array[];
}

/** Everything needed to build a DSP node in any context. */
export interface EngineAssets {
  readonly wasmBytes: ArrayBuffer;
  readonly compiled: CompiledPatch;
  readonly recordings: readonly DecodedRecording[];
}

/** A connected DSP node and its message link. */
export interface DspNode {
  readonly node: AudioWorkletNode;
  readonly link: WorkletLink;
}

const workletModules = new WeakMap<BaseAudioContext, Promise<void>>();

async function fetchBytes(url: URL): Promise<ArrayBuffer> {
  const response = await fetch(url);
  if (!response.ok) throw new Error(`Could not load ${url.href}: HTTP ${response.status}`);
  return response.arrayBuffer();
}

function resolveBase(baseUrl: string | undefined): URL {
  const page = globalThis.document?.baseURI ?? globalThis.location?.href;
  return new URL(baseUrl ?? "./", page);
}

async function decodeRecording(request: RecordingRequest, base: URL, decoder: BaseAudioContext): Promise<DecodedRecording> {
  const bytes = await fetchBytes(new URL(request.url, base));
  const buffer = await decoder.decodeAudioData(bytes);
  const channelCount = Math.min(buffer.numberOfChannels, 2);
  const channels = Array.from({ length: channelCount }, (_, channel) => buffer.getChannelData(channel).slice());
  return { instrumentIndex: request.instrumentIndex, midi: request.midi, rate: buffer.sampleRate, channels };
}

/** The SIMD core when this browser validates it, else the scalar core. */
async function fetchCore(): Promise<ArrayBuffer> {
  const simd = await fetchBytes(new URL("./dsp.wasm", import.meta.url));
  if (WebAssembly.validate(simd)) return simd;
  return fetchBytes(new URL("./dsp-scalar.wasm", import.meta.url));
}

/** Loads the WASM bytes and decodes every sampler recording in parallel. */
export async function loadAssets(compiled: CompiledPatch, baseUrl: string | undefined, decoder: BaseAudioContext): Promise<EngineAssets> {
  const base = resolveBase(baseUrl);
  const [wasmBytes, recordings] = await Promise.all([
    fetchCore(),
    Promise.all(compiled.recordings.map((request) => decodeRecording(request, base, decoder))),
  ]);
  return { wasmBytes, compiled, recordings };
}

function addWorkletModule(context: BaseAudioContext): Promise<void> {
  const existing = workletModules.get(context);
  if (existing) return existing;
  const added = context.audioWorklet.addModule(new URL("./processor.js", import.meta.url).href);
  workletModules.set(context, added);
  return added;
}

/** Builds a loaded DSP node and connects it to the destination. */
export async function createDspNode(context: BaseAudioContext, assets: EngineAssets): Promise<DspNode> {
  await addWorkletModule(context);
  const processorOptions: ProcessorSetup = { wasmBytes: assets.wasmBytes, program: assets.compiled.program };
  const node = new AudioWorkletNode(context, PROCESSOR_NAME, {
    numberOfInputs: 0,
    numberOfOutputs: 1,
    outputChannelCount: [2],
    processorOptions,
  });
  const link = new WorkletLink(node);
  for (const recording of assets.recordings) link.send({ type: "recording", ...recording });
  await link.sync();
  node.connect(context.destination);
  return { node, link };
}
